#!/usr/bin/env bash

#
# atf_image extracts the ATF binary image from DTB_FILE_NAME that appears in
# BR2_TARGET_ARM_TRUSTED_FIRMWARE_ADDITIONAL_VARIABLES in ${BR_CONFIG},
# then prints the corresponding file name for the genimage
# configuration file
#
atf_image()
{
	local ATF_VARIABLES="$(sed -n 's/^BR2_TARGET_ARM_TRUSTED_FIRMWARE_ADDITIONAL_VARIABLES="\(.*\)"$/\1/p' ${BR2_CONFIG})"

	local DTB_NAME="$(sed -n 's/.*DTB_FILE_NAME=\([^ ]*\)/\1/p' <<< ${ATF_VARIABLES})"
	local STM_NAME="tf-a-$(cut -f1 -d'.' <<< ${DTB_NAME}).stm32"
	echo ${STM_NAME}
}

dtb_base_name()
{
	local ATF_VARIABLES
	ATF_VARIABLES="$(sed -n 's/^BR2_TARGET_ARM_TRUSTED_FIRMWARE_ADDITIONAL_VARIABLES="\(.*\)"$/\1/p' ${BR2_CONFIG})"

	local DTB_NAME
	DTB_NAME="$(sed -n 's/.*DTB_FILE_NAME=\([^ ]*\)/\1/p' <<< ${ATF_VARIABLES})"

	cut -f1 -d'.' <<< "${DTB_NAME}"
}

main()
{
	local ATFBIN="$(atf_image)"
	if [ ! -e ${BINARIES_DIR}/${ATFBIN} ]; then
		echo "Can not find ATF binary ${ATFBIN}"
		exit 1
	fi

	local GENIMAGE_CFG=${2}
	local GENIMAGE_CFG_TMP="$(mktemp --suffix .genimage.cfg)"
	local GENIMAGE_TMP="${BUILD_DIR}/genimage.tmp"
	local SCRIPT_PATH=$(dirname "$0")

	# genimage.sh uses BINARIES_DIR as inputpath and an empty rootpath, so any
	# file referenced by genimage.cfg must exist under BINARIES_DIR.
	mkdir -p "${BINARIES_DIR}/extlinux"
	if [ -e "${TARGET_DIR}/boot/extlinux/extlinux.conf" ]; then
		cp -f "${TARGET_DIR}/boot/extlinux/extlinux.conf" "${BINARIES_DIR}/extlinux/extlinux.conf"
	fi

	sed -e "s/%ATFBIN%/${ATFBIN}/" \
		${SCRIPT_PATH}/${GENIMAGE_CFG} > ${GENIMAGE_CFG_TMP}

	support/scripts/genimage.sh -c ${GENIMAGE_CFG_TMP}

	rm -f ${GENIMAGE_CFG_TMP}

	# Produce standalone, fastboot-friendly artifacts (raw images) in BINARIES_DIR.
	local BOARD_BASENAME
	BOARD_BASENAME="$(dtb_base_name)"

	local FIP_OUT="fip-${BOARD_BASENAME}-optee.bin"
	local ROOTFS_OUT="qdsom-image-rootfs-${BOARD_BASENAME}.ext4"
	local USERFS_OUT="qdsom-image-userfs-${BOARD_BASENAME}.ext4"
	local UUU_AUTO_SOURCE="${SCRIPT_PATH}/deploy/uuu.auto"

	# fip.bin is produced by TF-A; keep a renamed copy for flashing.
	if [ -e "${BINARIES_DIR}/fip.bin" ]; then
		cp -f "${BINARIES_DIR}/fip.bin" "${BINARIES_DIR}/${FIP_OUT}"
	fi

	if [ -e "${BINARIES_DIR}/rootfs.ext4" ]; then
		cp -Lf "${BINARIES_DIR}/rootfs.ext4" "${BINARIES_DIR}/${ROOTFS_OUT}"
	fi

	# Userfs: generated by the A/B genimage layout as data.ext4.
	if [ -e "${BINARIES_DIR}/data.ext4" ]; then
		cp -f "${BINARIES_DIR}/data.ext4" "${BINARIES_DIR}/${USERFS_OUT}"
	fi

	# Keep the board-specific UUU script next to the generated flash artifacts.
	if [ -e "${UUU_AUTO_SOURCE}" ]; then
		cp -f "${UUU_AUTO_SOURCE}" "${BINARIES_DIR}/uuu.auto"
	fi

	if [ -e "${BINARIES_DIR}/sdcard.img" ]; then
		gzip -fk "${BINARIES_DIR}/sdcard.img"
		${HOST_DIR}/bin/bmaptool create -o "${BINARIES_DIR}/sdcard.img.bmap" "${BINARIES_DIR}/sdcard.img"
	else
		echo "sdcard.img not generated, skipping gzip/bmaptool"
	fi

	exit $?
}

main $@
